    BITMAPINFOHEADER outbi = bi;

    // Define new dimensions
    outbi.biWidth = scale * bi.biWidth;
    outbi.biHeight = scale * bi.biHeight;

    // Define new padding
    int outpadding = (4 - (outbi.biWidth * sizeof(RGBTRIPLE)) % 4) % 4;

    // Define new sizes
    outbi.biSizeImage = ((sizeof(RGBTRIPLE) * outbi.biWidth) + outpadding) * abs(outbi.biHeight);
    outbf.bfSize = outbi.biSizeImage + bf.bfOffBits;

    // Write outfile's BITMAPFILEHEADER
    fwrite(&outbf, sizeof(BITMAPFILEHEADER), 1, outptr);

    // Write outfile's BITMAPINFOHEADER
    fwrite(&outbi, sizeof(BITMAPINFOHEADER), 1, outptr);

    // Iterate over infile's scanlines
    for (int i = 0, biHeight = abs(bi.biHeight); i < biHeight; i++) {
        for (int h = 0; h < scale; h++) {
            // Iterate over pixels in scanline
            for (int j = 0; j < bi.biWidth; j++) {
                // Temporary storage
                RGBTRIPLE triple;

                // Read RGB triple from infile
                fread(&triple, sizeof(RGBTRIPLE), 1, inptr);

                // Write pixel per scale
                for (int w = 0; w < scale; w++) {
                    // Write RGB triple to outfile
                    fwrite(&triple, sizeof(RGBTRIPLE), 1, outptr);
                }

                // Skip over padding, if any
                fseek(inptr, padding, SEEK_CUR);

                // Then add it back (to demonstrate how)
                for (int k = 0; k < outpadding; k++) {
                    fputc(0x00, outptr);
                }
            }

            // Write padding after the scanline (to demonstrate how)
            for (int k = 0; k < outpadding; k++) {
                fputc(0x00, outptr);
            }
        }
    }

    // Close infile
    fclose(inptr);

    // Close outfile
    fclose(outptr);

    // Success
    return 0;
}
```

### Explanation of Changes:
1. **Padding Calculation**: The padding is now calculated correctly after each scanline.
2. **Writing Padding**: Padding is written after each scanline to ensure the correct alignment.
3. **Reading Padding**: Padding is read from the beginning of the file, ensuring it is correctly aligned with the scanlines.

